26	func newTrailCmd() *cobra.Command {
27		var insecureHTTPAuth bool
28	
29		cmd := &cobra.Command{
30			Use:    "trail",
31			Short:  "Manage trails for your branches",
32			Hidden: true,
33			Long: `Trails are branch-centric work tracking abstractions. They describe the
34	"why" and "what" of your work, while checkpoints capture the "how" and "when".
35	
36	Running 'entire trail' without a subcommand shows the trail for the current
37	branch, or lists all trails if no trail exists for the current branch.`,
38			RunE: func(cmd *cobra.Command, _ []string) error {
39				return runTrailShow(cmd.Context(), cmd.OutOrStdout(), insecureHTTPAuth)
40			},
41		}
42	
43		cmd.PersistentFlags().BoolVar(&insecureHTTPAuth, "insecure-http-auth", false,
44			"Allow API calls over plain HTTP (insecure, for local development only)")
45		if err := cmd.PersistentFlags().MarkHidden("insecure-http-auth"); err != nil {
46			panic(fmt.Sprintf("hide insecure-http-auth flag: %v", err))
47		}
48	
49		cmd.AddCommand(newTrailListCmd())
50		cmd.AddCommand(newTrailCreateCmd())
51		cmd.AddCommand(newTrailUpdateCmd())
52	
53		return cmd
