56	// trailInsecureHTTP reads the persistent --insecure-http-auth flag from the trail root command.
57	func trailInsecureHTTP(cmd *cobra.Command) bool {
58		v, _ := cmd.Flags().GetBool("insecure-http-auth") //nolint:errcheck // flag is always registered
59		return v
60	}
