62	// runTrailShow shows the trail for the current branch, or falls through to list.
63	func runTrailShow(ctx context.Context, w io.Writer, insecureHTTP bool) error {
64		branch, err := GetCurrentBranch(ctx)
65		if err != nil {
66			return runTrailListAll(ctx, w, "", false, false, insecureHTTP)
67		}
68	
69		client, err := NewAuthenticatedAPIClient(insecureHTTP)
70		if err != nil {
71			return fmt.Errorf("authentication required: %w", err)
72		}
73	
74		host, owner, repo, err := strategy.ResolveRemoteRepo(ctx, "origin")
75		if err != nil {
76			return fmt.Errorf("failed to resolve repository: %w", err)
77		}
78	
79		found, err := findTrailByBranch(ctx, client, host, owner, repo, branch)
80		if err != nil {
81			return err
82		}
83		if found == nil {
84			return runTrailListAll(ctx, w, "", false, false, insecureHTTP)
85		}
86	
87		printTrailDetails(w, found.ToMetadata())
88		return nil
89	}
