91	func printTrailDetails(w io.Writer, m *trail.Metadata) {
92		fmt.Fprintf(w, "Trail: %s\n", m.Title)
93		fmt.Fprintf(w, "  ID:      %s\n", m.TrailID)
94		fmt.Fprintf(w, "  Branch:  %s\n", m.Branch)
95		fmt.Fprintf(w, "  Base:    %s\n", m.Base)
96		fmt.Fprintf(w, "  Status:  %s\n", m.Status)
97		fmt.Fprintf(w, "  Author:  %s\n", m.Author)
98		if m.Body != "" {
99			fmt.Fprintf(w, "  Body:    %s\n", m.Body)
100		}
101		if len(m.Labels) > 0 {
102			fmt.Fprintf(w, "  Labels:  %s\n", strings.Join(m.Labels, ", "))
103		}
104		if len(m.Assignees) > 0 {
105			fmt.Fprintf(w, "  Assignees: %s\n", strings.Join(m.Assignees, ", "))
106		}
107		fmt.Fprintf(w, "  Created: %s\n", m.CreatedAt.Format("2006-01-02T15:04:05Z07:00"))
108		fmt.Fprintf(w, "  Updated: %s\n", m.UpdatedAt.Format("2006-01-02T15:04:05Z07:00"))
109	}
