131	func runTrailListAll(ctx context.Context, w io.Writer, statusFilter string, jsonOutput, showAll, insecureHTTP bool) error {
132		client, err := NewAuthenticatedAPIClient(insecureHTTP)
133		if err != nil {
134			return fmt.Errorf("authentication required: %w", err)
135		}
136	
137		host, owner, repo, err := strategy.ResolveRemoteRepo(ctx, "origin")
138		if err != nil {
139			return fmt.Errorf("failed to resolve repository: %w", err)
140		}
141	
142		resp, err := client.Get(ctx, trailsBasePath(host, owner, repo))
143		if err != nil {
144			return fmt.Errorf("failed to list trails: %w", err)
145		}
146		defer resp.Body.Close()
147		if err := checkTrailResponse(resp); err != nil {
148			return err
149		}
150	
151		var listResp api.TrailListResponse
152		if err := api.DecodeJSON(resp, &listResp); err != nil {
153			return fmt.Errorf("failed to decode trail list: %w", err)
154		}
155	
156		// Convert to metadata for display
157		trails := make([]*trail.Metadata, 0, len(listResp.Trails))
158		for i := range listResp.Trails {
159			trails = append(trails, listResp.Trails[i].ToMetadata())
160		}
161	
162		totalCount := len(trails)
163	
164		// Apply status filter
165		if statusFilter != "" {
166			status := trail.Status(statusFilter)
167			if !status.IsValid() {
168				return fmt.Errorf("invalid status %q: valid values are %s", statusFilter, formatValidStatuses())
169			}
170			var filtered []*trail.Metadata
171			for _, t := range trails {
172				if t.Status == status {
173					filtered = append(filtered, t)
174				}
175			}
176			trails = filtered
177		} else if !showAll {
178			// By default, hide merged and closed trails
179			var filtered []*trail.Metadata
180			for _, t := range trails {
181				if t.Status != trail.StatusMerged && t.Status != trail.StatusClosed {
182					filtered = append(filtered, t)
183				}
184			}
185			trails = filtered
186		}
187	
188		// Sort by updated_at descending
189		sort.Slice(trails, func(i, j int) bool {
190			return trails[i].UpdatedAt.After(trails[j].UpdatedAt)
191		})
192	
193		if jsonOutput {
194			enc := json.NewEncoder(w)
195			enc.SetIndent("", "  ")
196			if err := enc.Encode(trails); err != nil {
197				return fmt.Errorf("failed to encode JSON: %w", err)
198			}
199			return nil
200		}
201	
202		if len(trails) == 0 {
203			hiddenCount := totalCount - len(trails)
204			if hiddenCount > 0 {
205				fmt.Fprintf(w, "No active trails found. %d merged/closed trail(s) hidden — use --all to show.\n", hiddenCount)
206			} else {
207				fmt.Fprintln(w, "No trails found.")
208				fmt.Fprintln(w)
209				fmt.Fprintln(w, "Commands:")
210				fmt.Fprintln(w, "  entire trail create   Create a trail for the current branch")
211				fmt.Fprintln(w, "  entire trail list     List all trails")
212				fmt.Fprintln(w, "  entire trail update   Update trail metadata")
213			}
214			return nil
215		}
216	
217		// Table output
218		fmt.Fprintf(w, "%-30s %-40s %-13s %-15s %s\n", "BRANCH", "TITLE", "STATUS", "AUTHOR", "UPDATED")
219		for _, t := range trails {
220			branch := stringutil.TruncateRunes(t.Branch, 30, "...")
221			title := stringutil.TruncateRunes(t.Title, 40, "...")
222			fmt.Fprintf(w, "%-30s %-40s %-13s %-15s %s\n",
223				branch, title, t.Status, stringutil.TruncateRunes(t.Author, 15, "..."), timeAgo(t.UpdatedAt))
224		}
225	
226		return nil
227	}
