229	func newTrailCreateCmd() *cobra.Command {
230		var title, body, base, branch, status string
231		var checkout bool
232	
233		cmd := &cobra.Command{
234			Use:   "create",
235			Short: "Create a trail for the current or a new branch",
236			RunE: func(cmd *cobra.Command, _ []string) error {
237				return runTrailCreate(cmd, title, body, base, branch, status, checkout)
238			},
239		}
240	
241		cmd.Flags().StringVar(&title, "title", "", "Trail title")
242		cmd.Flags().StringVar(&body, "body", "", "Trail body")
243		cmd.Flags().StringVar(&base, "base", "", "Base branch (defaults to detected default branch)")
244		cmd.Flags().StringVar(&branch, "branch", "", "Branch for the trail (defaults to current branch)")
245		cmd.Flags().StringVar(&status, "status", "", "Initial status (defaults to draft)")
246		cmd.Flags().BoolVar(&checkout, "checkout", false, "Check out the branch after creating it")
247	
248		return cmd
249	}
