251	//nolint:cyclop // sequential steps for creating a trail — splitting would obscure the flow
252	func runTrailCreate(cmd *cobra.Command, title, body, base, branch, statusStr string, checkout bool) error {
253		ctx := cmd.Context()
254		w := cmd.OutOrStdout()
255		errW := cmd.ErrOrStderr()
256	
257		// --- Phase 1: Local git operations (no API calls) ---
258	
259		repo, err := strategy.OpenRepository(ctx)
260		if err != nil {
261			return fmt.Errorf("failed to open repository: %w", err)
262		}
263	
264		// Determine base branch
265		if base == "" {
266			base = strategy.GetDefaultBranchName(repo)
267			if base == "" {
268				base = defaultBaseBranch
269			}
270		}
271	
272		_, currentBranch, _ := IsOnDefaultBranch(ctx) //nolint:errcheck // best-effort detection
273		interactive := !cmd.Flags().Changed("title") && !cmd.Flags().Changed("branch")
274	
275		if interactive {
276			// Interactive flow: title → body → branch (derived) → status
277			if err := runTrailCreateInteractive(&title, &body, &branch, &statusStr); err != nil {
278				return handleFormCancellation(w, "Trail creation", err)
279			}
280		} else {
281			// Non-interactive: derive missing values from provided flags
282			if branch == "" {
283				if cmd.Flags().Changed("title") {
284					branch = slugifyTitle(title)
285				} else {
286					branch = currentBranch
287				}
288			}
289			if title == "" {
290				title = trail.HumanizeBranchName(branch)
291			}
292		}
293		if branch == "" {
294			return errors.New("branch name is required")
295		}
296	
297		// Create the local branch if it doesn't exist
298		needsCreation := branchNeedsCreation(repo, branch)
299		if needsCreation {
300			if err := createBranch(repo, branch); err != nil {
301				return fmt.Errorf("failed to create branch %q: %w", branch, err)
302			}
303			fmt.Fprintf(w, "Created branch %s\n", branch)
304		} else if currentBranch != branch {
305			fmt.Fprintf(w, "Note: trail will be created for branch %q (not the current branch)\n", branch)
306		}
307	
308		// Push the branch so the API can reference it
309		if needsCreation {
310			if err := pushBranchToOrigin(branch); err != nil {
311				fmt.Fprintf(errW, "Warning: failed to push branch: %v\n", err)
312			} else {
313				fmt.Fprintf(w, "Pushed branch %s to origin\n", branch)
314			}
315		}
316	
317		// --- Phase 2: API operations ---
318	
319		client, err := NewAuthenticatedAPIClient(trailInsecureHTTP(cmd))
320		if err != nil {
321			return fmt.Errorf("authentication required: %w", err)
322		}
323	
324		host, owner, repoName, err := strategy.ResolveRemoteRepo(ctx, "origin")
325		if err != nil {
326			return fmt.Errorf("failed to resolve repository: %w", err)
327		}
328	
329		createReq := api.TrailCreateRequest{
330			Title:      title,
331			Body:       body,
332			BranchName: branch,
333			Base:       base,
334			Status:     statusStr,
335		}
336	
337		resp, err := client.Post(ctx, trailsBasePath(host, owner, repoName), createReq)
338		if err != nil {
339			return fmt.Errorf("failed to create trail: %w", err)
340		}
341		defer resp.Body.Close()
342		if err := checkTrailResponse(resp); err != nil {
343			return err
344		}
345	
346		var createResp api.TrailCreateResponse
347		if err := api.DecodeJSON(resp, &createResp); err != nil {
348			return fmt.Errorf("failed to decode create response: %w", err)
349		}
350	
351		fmt.Fprintf(w, "Created trail %q for branch %s (ID: %s)\n", createResp.Trail.Title, createResp.Trail.Branch, createResp.Trail.TrailID)
352	
353		// --- Phase 3: Post-creation local operations ---
354	
355		if needsCreation && currentBranch != branch {
356			shouldCheckout := checkout
357			if !shouldCheckout && !cmd.Flags().Changed("checkout") {
358				// Interactive: ask whether to checkout
359				form := NewAccessibleForm(
360					huh.NewGroup(
361						huh.NewConfirm().
362							Title(fmt.Sprintf("Check out branch %s?", branch)).
363							Value(&shouldCheckout),
364					),
365				)
366				if formErr := form.Run(); formErr == nil && shouldCheckout {
367					checkout = true
368				}
369			}
370			if checkout {
371				if err := CheckoutBranch(ctx, branch); err != nil {
372					return fmt.Errorf("failed to checkout branch %q: %w", branch, err)
373				}
374				fmt.Fprintf(w, "Switched to branch %s\n", branch)
375			}
376		}
377	
378		return nil
379	}
380	
381	func newTrailUpdateCmd() *cobra.Command {
382		var statusStr, title, body, branch string
383		var labelAdd, labelRemove []string
384	
385		cmd := &cobra.Command{
386			Use:   "update",
387			Short: "Update trail metadata",
388			RunE: func(cmd *cobra.Command, _ []string) error {
389				return runTrailUpdate(cmd.Context(), cmd.OutOrStdout(), cmd.ErrOrStderr(), trailInsecureHTTP(cmd), statusStr, title, body, branch, labelAdd, labelRemove)
390			},
391		}
392	
393		cmd.Flags().StringVar(&statusStr, "status", "", "Update status")
394		cmd.Flags().StringVar(&title, "title", "", "Update title")
395		cmd.Flags().StringVar(&body, "body", "", "Update body")
396		cmd.Flags().StringVar(&branch, "branch", "", "Branch to update trail for (defaults to current)")
397		cmd.Flags().StringSliceVar(&labelAdd, "add-label", nil, "Add label(s)")
398		cmd.Flags().StringSliceVar(&labelRemove, "remove-label", nil, "Remove label(s)")
399	
400		return cmd
401	}
402	
403	func runTrailUpdate(ctx context.Context, w, errW io.Writer, insecureHTTP bool, statusStr, title, body, branch string, labelAdd, labelRemove []string) error {
404		_ = errW // reserved for future warnings
405	
406		client, err := NewAuthenticatedAPIClient(insecureHTTP)
407		if err != nil {
408			return fmt.Errorf("authentication required: %w", err)
409		}
410	
411		host, owner, repoName, err := strategy.ResolveRemoteRepo(ctx, "origin")
412		if err != nil {
413			return fmt.Errorf("failed to resolve repository: %w", err)
414		}
415	
416		// Determine branch
417		if branch == "" {
418			branch, err = GetCurrentBranch(ctx)
419			if err != nil {
420				return fmt.Errorf("failed to determine current branch: %w", err)
421			}
422		}
423	
424		// Find the trail by branch
425		found, err := findTrailByBranch(ctx, client, host, owner, repoName, branch)
426		if err != nil {
427			return err
428		}
429		if found == nil {
430			return fmt.Errorf("no trail found for branch %q", branch)
431		}
432	
433		// Interactive mode when no flags are provided
434		noFlags := statusStr == "" && title == "" && body == "" && labelAdd == nil && labelRemove == nil
435		if noFlags {
436			metadata := found.ToMetadata()
437			// Build status options with current value as default.
438			var statusOptions []huh.Option[string]
439			for _, s := range trail.ValidStatuses() {
440				if (s == trail.StatusMerged || s == trail.StatusClosed) && s != metadata.Status {
441					continue
442				}
443				label := string(s)
444				if s == metadata.Status {
445					label += " (current)"
446				}
447				statusOptions = append(statusOptions, huh.NewOption(label, string(s)))
448			}
449			statusStr = string(metadata.Status)
450			title = metadata.Title
451			body = metadata.Body
452	
453			form := NewAccessibleForm(
454				huh.NewGroup(
455					huh.NewSelect[string]().
456						Title("Status").
457						Options(statusOptions...).
458						Value(&statusStr),
459					huh.NewInput().
460						Title("Title").
461						Value(&title),
462					huh.NewText().
463						Title("Body").
464						Value(&body),
465				),
466			)
467			if formErr := form.Run(); formErr != nil {
468				return handleFormCancellation(w, "Trail update", formErr)
469			}
470		}
471	
472		// Validate status if provided
473		if statusStr != "" {
474			status := trail.Status(statusStr)
475			if !status.IsValid() {
476				return fmt.Errorf("invalid status %q: valid values are %s", statusStr, formatValidStatuses())
477			}
478		}
479	
480		// Build update request with only changed fields
481		updateReq := buildTrailUpdateRequest(found, statusStr, title, body, labelAdd, labelRemove)
482	
483		resp, err := client.Patch(ctx, trailsBasePath(host, owner, repoName)+"/"+found.TrailID, updateReq)
484		if err != nil {
485			return fmt.Errorf("failed to update trail: %w", err)
486		}
487		defer resp.Body.Close()
488		if err := checkTrailResponse(resp); err != nil {
489			return err
490		}
491	
492		var updateResp api.TrailUpdateResponse
493		if err := api.DecodeJSON(resp, &updateResp); err != nil {
494			return fmt.Errorf("failed to decode update response: %w", err)
495		}
496	
497		fmt.Fprintf(w, "Updated trail for branch %s\n", branch)
498		return nil
499	}
500	
501	// buildTrailUpdateRequest constructs a PATCH request body from the current trail and the requested changes.
502	func buildTrailUpdateRequest(current *api.TrailResource, statusStr, title, body string, labelAdd, labelRemove []string) api.TrailUpdateRequest {
503		var req api.TrailUpdateRequest
504	
505		if statusStr != "" {
506			req.Status = &statusStr
507		}
508		if title != "" {
509			req.Title = &title
510		}
511		if body != "" {
512			req.Body = &body
513		}
514	
515		// Handle label changes: merge adds, remove removes
516		if len(labelAdd) > 0 || len(labelRemove) > 0 {
517			labels := make([]string, 0, len(current.Labels)+len(labelAdd))
518			labels = append(labels, current.Labels...)
519			for _, l := range labelAdd {
520				found := false
521				for _, existing := range labels {
522					if existing == l {
523						found = true
524						break
525					}
526				}
527				if !found {
528					labels = append(labels, l)
529				}
530			}
531			for _, l := range labelRemove {
532				for i, existing := range labels {
533					if existing == l {
534						labels = append(labels[:i], labels[i+1:]...)
535						break
536					}
537				}
538			}
539			req.Labels = &labels
540		}
541	
542		return req
543	}
544	
545	// defaultBaseBranch is the fallback base branch name when it cannot be determined.
546	const defaultBaseBranch = "main"
547	
548	func formatValidStatuses() string {
549		statuses := trail.ValidStatuses()
550		names := make([]string, len(statuses))
551		for i, s := range statuses {
552			names[i] = string(s)
553		}
554		return strings.Join(names, ", ")
555	}
556	
557	// runTrailCreateInteractive runs the interactive form for trail creation.
558	// Prompts for title, body, branch (derived from title), and status.
559	func runTrailCreateInteractive(title, body, branch, statusStr *string) error {
560		// Step 1: Title and body
561		form := NewAccessibleForm(
562			huh.NewGroup(
563				huh.NewInput().
564					Title("Trail title").
565					Placeholder("What are you working on?").
566					Value(title),
567				huh.NewText().
568					Title("Body (optional)").
569					Value(body),
570			),
571		)
572		if err := form.Run(); err != nil {
573			return fmt.Errorf("form cancelled: %w", err)
574		}
575		*title = strings.TrimSpace(*title)
576		if *title == "" {
577			return errors.New("trail title is required")
578		}
579	
580		// Step 2: Branch (derived from title) and status
581		suggested := slugifyTitle(*title)
582		*branch = suggested
583	
584		// Build status options, excluding done/closed
585		var statusOptions []huh.Option[string]
586		for _, s := range trail.ValidStatuses() {
587			if s == trail.StatusMerged || s == trail.StatusClosed {
588				continue
589			}
590			statusOptions = append(statusOptions, huh.NewOption(string(s), string(s)))
591		}
592		if *statusStr == "" {
593			*statusStr = string(trail.StatusDraft)
594		}
595	
596		form = NewAccessibleForm(
597			huh.NewGroup(
598				huh.NewInput().
599					Title("Branch name").
600					Placeholder(suggested).
601					Value(branch),
602				huh.NewSelect[string]().
603					Title("Status").
604					Options(statusOptions...).
605					Value(statusStr),
606			),
607		)
608		if err := form.Run(); err != nil {
609			return fmt.Errorf("form cancelled: %w", err)
610		}
611		*branch = strings.TrimSpace(*branch)
612		if *branch == "" {
613			*branch = suggested
614		}
615		return nil
616	}
617	
618	// findTrailByBranch looks up a trail by branch name via the list API.
619	func findTrailByBranch(ctx context.Context, client *api.Client, host, owner, repo, branch string) (*api.TrailResource, error) {
620		resp, err := client.Get(ctx, trailsBasePath(host, owner, repo))
621		if err != nil {
622			return nil, fmt.Errorf("list trails: %w", err)
623		}
624		defer resp.Body.Close()
625		if err := checkTrailResponse(resp); err != nil {
626			return nil, err
627		}
628	
629		var listResp api.TrailListResponse
630		if err := api.DecodeJSON(resp, &listResp); err != nil {
631			return nil, fmt.Errorf("decode trail list: %w", err)
632		}
633	
634		for i := range listResp.Trails {
635			if listResp.Trails[i].Branch == branch {
636				return &listResp.Trails[i], nil
637			}
638		}
639		return nil, nil //nolint:nilnil // nil, nil means "not found" — callers check both
640	}
641	
642	// apiHostAlias maps git host domains to short aliases used by the trails API.
643	var apiHostAlias = map[string]string{
644		"github.com": "gh",
645	}
646	
647	// trailsBasePath returns the API path prefix for trails endpoints (e.g., "/api/v1/trails/gh/org/repo").
648	func trailsBasePath(host, owner, repo string) string {
649		if alias, ok := apiHostAlias[host]; ok {
650			host = alias
651		}
652		return fmt.Sprintf("/api/v1/trails/%s/%s/%s", host, owner, repo)
653	}
654	
655	// checkTrailResponse checks the API response and returns user-friendly errors.
656	// For auth failures, it appends a hint to re-authenticate while preserving the server's error message.
657	func checkTrailResponse(resp *http.Response) error {
658		if err := api.CheckResponse(resp); err != nil {
659			if resp.StatusCode == http.StatusUnauthorized || resp.StatusCode == http.StatusForbidden {
660				return fmt.Errorf("%w — run 'entire login' to re-authenticate", err)
661			}
662			return fmt.Errorf("trail API: %w", err)
663		}
664		return nil
665	}
666	
667	// slugifyTitle converts a title string into a branch-friendly slug.
668	// Example: "Add user authentication" -> "add-user-authentication"
669	func slugifyTitle(title string) string {
670		s := strings.ToLower(strings.TrimSpace(title))
671		// Replace spaces and underscores with hyphens
672		s = strings.NewReplacer(" ", "-", "_", "-").Replace(s)
673		// Remove anything that's not alphanumeric, hyphen, or slash
674		var b strings.Builder
675		prevHyphen := false
676		for _, r := range s {
677			if (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9') || r == '/' {
678				b.WriteRune(r)
679				prevHyphen = false
680			} else if r == '-' && !prevHyphen {
681				b.WriteRune('-')
682				prevHyphen = true
683			}
684		}
685		return strings.Trim(b.String(), "-")
686	}
687	
688	// branchNeedsCreation checks if a branch exists locally.
689	func branchNeedsCreation(repo *git.Repository, branchName string) bool {
690		_, err := repo.Reference(plumbing.NewBranchReferenceName(branchName), true)
691		return err != nil
692	}
693	
694	// createBranch creates a new local branch pointing at HEAD without checking it out.
695	func createBranch(repo *git.Repository, branchName string) error {
696		head, err := repo.Head()
697		if err != nil {
698			return fmt.Errorf("failed to get HEAD: %w", err)
699		}
700		ref := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), head.Hash())
701		if err := repo.Storer.SetReference(ref); err != nil {
702			return fmt.Errorf("failed to create branch ref: %w", err)
703		}
704		return nil
705	}
706	
707	// pushBranchToOrigin pushes a branch to the origin remote.
708	func pushBranchToOrigin(branchName string) error {
709		ctx, cancel := context.WithTimeout(context.Background(), 2*time.Minute)
710		defer cancel()
711		cmd := exec.CommandContext(ctx, "git", "push", "--no-verify", "-u", "origin", branchName)
712		if output, err := cmd.CombinedOutput(); err != nil {
713			return fmt.Errorf("%s: %w", strings.TrimSpace(string(output)), err)
714		}
715		return nil
716	}
